class Solution {
    public String interpret(String command) {
        return command.replace("()", "o").replace("(al)", "al");
    }
}

class Solution {
    public String interpret(String command) {
        StringBuilder answer = new StringBuilder();
        int i = 0;
        while (i < command.length()) {
            if (command.charAt(i) == 'G') {
                answer.append('G');
                i++;
            } else if (command.charAt(i + 1) == ')') {
                answer.append('o');
                i += 2;
            } else {
                answer.append("al");
                i += 4;
            }
        }
        return answer.toString();
    }
}

class Solution {
    public String interpret(String command) {
        StringBuilder answer = new StringBuilder();
        int i = 0;
        while (i < command.length()) {
            if (command.startsWith("G", i)) {
                answer.append("G");
                i += 1;
            } else if (command.startsWith("()", i)) {
                answer.append("o");
                i += 2;
            } else {
                answer.append("al");
                i += 4;
            }
        }
        return answer.toString();
    }
}

class Solution {
    public String interpret(String command) {
        String[] tokens = {"(al)", "()", "G"};
        String[] meanings = {"al", "o", "G"};
        StringBuilder answer = new StringBuilder();
        int i = 0;
        while (i < command.length()) {
            for (int t = 0; t < tokens.length; t++) {
                if (command.startsWith(tokens[t], i)) {
                    answer.append(meanings[t]);
                    i += tokens[t].length();
                    break;
                }
            }
        }
        return answer.toString();
    }
}
